/**
 * 종목상세정보 팝업창
 */
/**
 * @method
 * @name fn_OpenDetailRecv
 * @description desc
 * @param {string} vbzTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenDetailRecv = async function(vbzTpCd) {
    var screenId = "";
    var screenNm = "";
    if (vbzTpCd == LIST_BZ_TP_CD_002) {
        screenId = "ULDSTF05902";
        screenNm = "ELW심사청구내역";
    } else if (vbzTpCd == LIST_BZ_TP_CD_003) {
        screenId = "ULDSTF05927";
        screenNm = "ELW상장신청내역";
    } else if (vbzTpCd == LIST_BZ_TP_CD_004) {
        screenId = "ULDSTF05928";
        screenNm = "ELW추가상장심사청구내역";
    } else if (vbzTpCd == LIST_BZ_TP_CD_005) {
        screenId = "ULDSTF05929";
        screenNm = "ELW추가상장신청내역";
    }
    await $c.frame.CreateDialogFrame("DLG_ELWRECV", "/lstproc/" + screenId + ".gfm", screenNm, 10, 10, 1050, 850, "window");
};


