/**
 * @method
 * @name fn_setCheckBox
 * @description desc
 * @param {string} grdObj desc
 * @param {string} dtsObj desc
 * @param {string} bCheck desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setCheckBox = function(grdObj, dtsObj, bCheck) {
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        dtsObj.setCellData(i, "CHECK", vcd);
    }
    grdObj.setBroadcast(true);
};
/**
 * @method
 * @name fn_searchCode
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_searchCode = function() {
    /*
    00685 - 명의개서대행기관
    01277 - ELW대상지수구분코드
    01353 - ELW권리형태종류코드
    01402 - 자동권리행사구분코드
    01292 - ELW권리유형코드
    00055 - 권리행사유형코드
    00665 - 금융기초자산구분코드
    */
    var arrCid = [{
        cid: "00685",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "01277",
        cnm: "cmb_ELW_OBJ_IDX_TP_CD"
    }, {
        cid: "01353",
        cnm: "cmb_ELW_RGHT_TP_KIND_CD"
    }, {
        cid: "01402",
        cnm: "cmb_AUTO_EXER_TP_CD"
    }, {
        cid: "01292",
        cnm: "cmb_ELW_RGHT_TP_CD"
    }, {
        cid: "00055",
        cnm: "cmb_ELW_EXER_TP_CD"
    }, {
        cid: "00665",
        cnm: "cmb_FNC_ULY_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='00685','01277','01353','01402','01292','00055','00665'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ID") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};




/**
 * 예비심사, 상장신청 종목정보를 read
 */
/**
 * @method
 * @name fn_elwisu_read_sync
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_elwisu_read_sync = function(dtsObj, vKey) {
    var url = "";
    url += "/ElwListedReceive.do?method=readElwIsuReceipt&inputMessageId=ELW_ISU_RECEIPT_LSTRCV_INOUT";
    url += "&BZ_PROCS_NO=" + vKey;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
};


