/**
 * 종목정보 재무정보, 영업용순자본비율을 read
 */
/**
 * @method
 * @name fn_setFnc
 * @description desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setFnc = function(dtsObj) {
    //결산연월
    //alert('1   ACNTCLS_YYMM'+dtsObj.NameString(1, "ACNTCLS_YYMM"));
    edt_ACNTCLS_YYMM_1.setValue(dtsObj.getCellData(1, "ACNTCLS_YYMM"));
    edt_ACNTCLS_YYMM_2.setValue(dtsObj.getCellData(2, "ACNTCLS_YYMM"));
    edt_ACNTCLS_YYMM_3.setValue(dtsObj.getCellData(3, "ACNTCLS_YYMM"));

    //감사의견구분코드
    txb_AUDT_OPIN_TP_CD_1.setValue(dtsObj.getCellData(1, "AUDT_OPIN_TP_NM"));
    txb_AUDT_OPIN_TP_CD_2.setValue(dtsObj.getCellData(2, "AUDT_OPIN_TP_NM"));
    txb_AUDT_OPIN_TP_CD_3.setValue(dtsObj.getCellData(3, "AUDT_OPIN_TP_NM"));


    //자산총계
    edt_TOT_ASST_AMT_1.setValue(dtsObj.getCellData(1, "TOT_ASST_AMT"));
    edt_TOT_ASST_AMT_2.setValue(dtsObj.getCellData(2, "TOT_ASST_AMT"));
    edt_TOT_ASST_AMT_3.setValue(dtsObj.getCellData(3, "TOT_ASST_AMT"));

    //부채총계
    edt_TOT_DEBT_AMT_1.setValue(dtsObj.getCellData(1, "TOT_DEBT_AMT"));
    edt_TOT_DEBT_AMT_2.setValue(dtsObj.getCellData(2, "TOT_DEBT_AMT"));
    edt_TOT_DEBT_AMT_3.setValue(dtsObj.getCellData(3, "TOT_DEBT_AMT"));

    //자본총계
    edt_TOT_CAP_1.setValue(dtsObj.getCellData(1, "TOT_CAP"));
    edt_TOT_CAP_2.setValue(dtsObj.getCellData(2, "TOT_CAP"));
    edt_TOT_CAP_3.setValue(dtsObj.getCellData(3, "TOT_CAP"));

    //자본금
    edt_CAP_1.setValue(dtsObj.getCellData(1, "CAP"));
    edt_CAP_2.setValue(dtsObj.getCellData(2, "CAP"));
    edt_CAP_3.setValue(dtsObj.getCellData(3, "CAP"));

    //영업이익금액
    edt_BZ_PROFT_AMT_1.setValue(dtsObj.getCellData(1, "BZ_PROFT_AMT"));
    edt_BZ_PROFT_AMT_2.setValue(dtsObj.getCellData(2, "BZ_PROFT_AMT"));
    edt_BZ_PROFT_AMT_3.setValue(dtsObj.getCellData(3, "BZ_PROFT_AMT"));

    //경상이익금액
    edt_ORDNINCM_AMT_1.setValue(dtsObj.getCellData(1, "ORDNINCM_AMT"));
    edt_ORDNINCM_AMT_2.setValue(dtsObj.getCellData(2, "ORDNINCM_AMT"));
    edt_ORDNINCM_AMT_3.setValue(dtsObj.getCellData(3, "ORDNINCM_AMT"));

    //당기순이익금액
    edt_NETINCM_AMT_1.setValue(dtsObj.getCellData(1, "NETINCM_AMT"));
    edt_NETINCM_AMT_2.setValue(dtsObj.getCellData(2, "NETINCM_AMT"));
    edt_NETINCM_AMT_3.setValue(dtsObj.getCellData(3, "NETINCM_AMT"));

    //영업활동현금흐름금액
    edt_BZ_ACTIV_CASH_FLOW_AMT_1.setValue(dtsObj.getCellData(1, "BZ_ACTIV_CASH_FLOW_AMT"));
    edt_BZ_ACTIV_CASH_FLOW_AMT_2.setValue(dtsObj.getCellData(2, "BZ_ACTIV_CASH_FLOW_AMT"));
    edt_BZ_ACTIV_CASH_FLOW_AMT_3.setValue(dtsObj.getCellData(3, "BZ_ACTIV_CASH_FLOW_AMT"));

    //결산연월
    edt_ACNTCLS_YYMM_4.setValue(dtsObj.getCellData(1, "ACNTCLS_YYMM"));
    edt_ACNTCLS_YYMM_5.setValue(dtsObj.getCellData(2, "ACNTCLS_YYMM"));
    edt_ACNTCLS_YYMM_6.setValue(dtsObj.getCellData(3, "ACNTCLS_YYMM"));

    //영업용순자본금
    edt_FBZ_NETCAP_1.setValue(dtsObj.getCellData(1, "FBZ_NETCAP"));
    edt_FBZ_NETCAP_2.setValue(dtsObj.getCellData(2, "FBZ_NETCAP"));
    edt_FBZ_NETCAP_3.setValue(dtsObj.getCellData(3, "FBZ_NETCAP"));

    //총위험금액
    edt_TOT_RISK_AMT_1.setValue(dtsObj.getCellData(1, "TOT_RISK_AMT"));
    edt_TOT_RISK_AMT_2.setValue(dtsObj.getCellData(2, "TOT_RISK_AMT"));
    edt_TOT_RISK_AMT_3.setValue(dtsObj.getCellData(3, "TOT_RISK_AMT"));

    //영업용순자본비율
    edt_FBZ_NETCAP_RT_1.setValue(dtsObj.getCellData(1, "FBZ_NETCAP_RT"));
    edt_FBZ_NETCAP_RT_2.setValue(dtsObj.getCellData(2, "FBZ_NETCAP_RT"));
    edt_FBZ_NETCAP_RT_3.setValue(dtsObj.getCellData(3, "FBZ_NETCAP_RT"));
};



/**
 * 종목정보 장외파생정보을 read
 */
/**
 * @method
 * @name fn_seOtctFnc
 * @description desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_seOtctFnc = function(dtsObj) {
    //기준일자
    edt_BAS_DD_1.setValue(dtsObj.getCellData(1, "BAS_DD"));
    edt_BAS_DD_2.setValue(dtsObj.getCellData(2, "BAS_DD"));
    edt_BAS_DD_3.setValue(dtsObj.getCellData(3, "BAS_DD"));

    //자기자본금
    edt_EQTYCAP_1.setValue(dtsObj.getCellData(1, "EQTYCAP"));
    edt_EQTYCAP_2.setValue(dtsObj.getCellData(2, "EQTYCAP"));

    //장외파생금융상품거래총위험금액
    edt_OTC_DRVFNC_TRD_TOT_RISK_AMT_1.setValue(dtsObj.getCellData(1, "OTC_DRVFNC_TRD_TOT_RISK_AMT"));
    edt_OTC_DRVFNC_TRD_TOT_RISK_AMT_2.setValue(dtsObj.getCellData(2, "OTC_DRVFNC_TRD_TOT_RISK_AMT"));

    //자기자본금비율
    edt_EQTYCAP_RT_1.setValue(dtsObj.getCellData(1, "EQTYCAP_RT"));
    edt_EQTYCAP_RT_2.setValue(dtsObj.getCellData(2, "EQTYCAP_RT"));

    //alert('EQTYCAP_RT 1'+dtsObj.NameString(1, "EQTYCAP_RT"));
    var eqtycap_1 = edt_EQTYCAP_1.getValue();
    var eqtycap_2 = edt_EQTYCAP_2.getValue();
    edt_EQTYCAP_3.setValue(parseInt(parseInt(eqtycap_1) - parseInt(eqtycap_2)));
    var trdTotAmt_1 = edt_OTC_DRVFNC_TRD_TOT_RISK_AMT_1.getValue();
    var trdTotAmt_2 = edt_OTC_DRVFNC_TRD_TOT_RISK_AMT_2.getValue();
    edt_OTC_DRVFNC_TRD_TOT_RISK_AMT_3.setValue(parseInt(parseInt(trdTotAmt_1) - parseInt(trdTotAmt_2)));
    var eqtycaprt_1 = edt_EQTYCAP_RT_1.getValue();
    var eqtycaprt_2 = edt_EQTYCAP_RT_2.getValue();
    edt_EQTYCAP_RT_3.setValue(parseFloat(parseFloat(eqtycaprt_1) - parseFloat(eqtycaprt_2)));
};



/**
 * 종목정보 파일다운로드
 */
/**
 * @method
 * @name fn_filedown
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vKey desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_filedown = function(dtsObj, vKey) {
    var attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ELW_ATTACH_SEQ");
    location.href = "/filedownload.do?file_id=" + vKey + "&attach_seq=" + attach_seq + "&gubun=4"; //gubun = 4:elw 

};
/**
 * @method
 * @name fn_getArrIsuNmInfo
 * @description desc
 * @param {string} arrStr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getArrIsuNmInfo = function(arrStr) {
    var oldVar;
    var bgnVar;
    var endVar = "N/A";
    var parStr;
    var msgStr = "";
    var numIsu = 0;
    arrStr.sort();
    for (i = 0; i < arrStr.length + 1; i++) {
        //alert("org data : " + arrStr[i]);
        if (oldVar != arrStr[i]) {
            if (parseInt(arrStr[i] - oldVar) < 2) {
                //alert("contiguous data : " + arrStr[i]);
                endVar = arrStr[i];
            } else {
                //alert("not contiguous data :" + arrStr[i]);
                if (endVar != "N/A") {
                    if (endVar != "") {
                        //alert(bgnVar + "~" + endVar + "회, ");
                        msgStr = msgStr + "제" + bgnVar + "호" + "~" + "제" + endVar + "호" + ", ";
                    } else {
                        //alert(oldVar + "회, ");
                        msgStr = msgStr + "제" + oldVar + "호" + ", ";
                    }
                }
                bgnVar = arrStr[i];
                endVar = "";
            }
            numIsu++;
        }
        oldVar = arrStr[i];
    }
    numIsu--;

    //alert('[msgStr]'+msgStr);
    msgStr = msgStr.substr(0, msgStr.length - 2);
    var arrPar = new Array();
    arrPar[0] = {
        ISUR_STR: msgStr,
        ISUR_CNT: numIsu
    };
    return arrPar;
};


/**
 * 예비심청구 인쇄
 */
/**
 * @method
 * @name fn_getUlyIsuArr
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getUlyIsuArr = function() {
    var arrPar = new Array();
    if (cmb_FNC_ULY_TP_CD.getValue() == '3') {
        arrPar[0] = {
            ULY_ISU_NM: $c.stf.fn_getComboTextValue(cmb_ELW_OBJ_IDX_TP_CD),
            ULY_ISU_CD: '',
            ULY_COMPST_RTO: '1'
        };
    }
    for (var i = 1, k = 0; i <= dts_UlyIsu.getTotalRow();
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        i++, k++) {
        arrPar[k] = {
            ULY_ISU_NM: dts_UlyIsu.getCellData(i, "ULY_ISU_NM"),
            ULY_ISU_CD: dts_UlyIsu.getCellData(i, "ULY_ISU_CD"),
            ULY_COMPST_RTO: dts_UlyIsu.getCellData(i, "ULY_COMPST_RTO")
        };
    }

    //alert('[arrUlyIsu.length]'+arrUlyIsu.length);
    for (var j = arrPar.length; j < 5; j++) {
        arrPar[j] = {
            ULY_ISU_NM: '',
            ULY_ISU_CD: '',
            ULY_COMPST_RTO: ''
        };
    }
    return arrPar;
};
